use std::path::PathBuf;
use std::time::Duration;

use secrecy::{ExposeSecret, SecretString};
use serde::Deserialize;
use serde_aux::field_attributes::deserialize_number_from_string;
use sqlx::ConnectOptions;
use sqlx::postgres::{PgConnectOptions, PgSslMode};
use url::Url;

#[derive(serde::Deserialize, Clone)]
pub struct Settings {
    pub database: DatabaseSettings,
    pub application: ApplicationSettings,
    pub log: LogSettings,
    pub cors: CorsSettings,
    pub auth: AuthSettings,
    #[serde(default)]
    pub mqtt: MqttSettings,
    #[serde(default)]
    pub map: MapSettings,
    #[serde(default)]
    pub info: InfoSettings,
    #[serde(default)]
    pub sensor: SensorSettings,
    #[serde(default)]
    pub watering: WateringSettings,
    #[serde(default)]
    pub routing: RoutingSettings,
    #[serde(default)]
    pub plugins: PluginsSettings,
    #[serde(default)]
    pub analytics: AnalyticsSettings,
}

#[derive(serde::Deserialize, Clone)]
pub struct DatabaseSettings {
    pub username: String,
    pub password: SecretString,
    #[serde(deserialize_with = "deserialize_number_from_string")]
    pub port: u16,
    pub host: String,
    pub database_name: String,
    #[serde(default = "default_schema")]
    pub schema: String,
    pub require_ssl: bool,
    #[serde(deserialize_with = "deserialize_number_from_string")]
    pub max_connections: u32,
    pub log_statements_level: LogLevel,
    #[serde(deserialize_with = "deserialize_number_from_string")]
    pub slow_query_threshold_ms: u64,
}

fn default_schema() -> String {
    "public".to_string()
}

// Non-public schemas still need `public` on the path so PostGIS/pgcrypto
// (installed there on managed Postgres) resolve unqualified. No spaces:
// the value is passed as a single `-c search_path=...` connection option.
pub fn search_path_for(schema: &str) -> String {
    if schema == "public" {
        "public".to_string()
    } else {
        format!("{schema},public")
    }
}

impl DatabaseSettings {
    pub fn connection_options(&self) -> PgConnectOptions {
        let ssl_mode = if self.require_ssl {
            PgSslMode::Require
        } else {
            PgSslMode::Prefer
        };

        PgConnectOptions::new()
            .host(&self.host)
            .username(&self.username)
            .password(self.password.expose_secret())
